<?php
namespace App\Http\Controllers\Api\Admin;
use App\Http\Controllers\Controller;use App\Models\MarketplaceDeliveryZone;use Illuminate\Http\Request;
class MarketplaceDeliveryZoneController extends Controller {public function index(){return MarketplaceDeliveryZone::orderBy('fee')->get();}public function store(Request $request){return response()->json(MarketplaceDeliveryZone::create($this->validated($request)),201);}public function update(Request $request,MarketplaceDeliveryZone $zone){$zone->update($this->validated($request));return $zone;}public function destroy(MarketplaceDeliveryZone $zone){abort_if($zone->orders()->exists(),422,'This zone has existing orders and cannot be deleted. Disable it instead.');$zone->delete();return response()->json(null,204);}private function validated(Request $request):array{return $request->validate(['name'=>['required','string','max:120'],'state'=>['nullable','string','max:100'],'cities'=>['nullable','array'],'cities.*'=>['string','max:100'],'fee'=>['required','numeric','min:0'],'estimated_delivery'=>['nullable','string','max:100'],'is_active'=>['required','boolean']]);}}
